    if isinstance(scope, dict) and not isinstance(scope, ChainMap):
        scope = ChainMap(scope, _DEFAULT_SCOPE)
    elif not isinstance(scope, ChainMap):
        scope = ChainMap(dict(scope), _DEFAULT_SCOPE)

    scope = scope.new_child({
        Path: [],
        T: target,
        Spec: spec,
        UP: scope,
        LAST_CHILD_SCOPE: scope,
        CHILD_ERRORS: [],
        MODE: AUTO,
        MIN_MODE: AUTO,
        NO_PYFRAME: True,
    })

    try:
        ret = scope[glom](target, spec, scope)
    except skip_exc as e:
        if default is _MISSING:
            raise
        ret = default
    except GlomError as e:
        if not glom_debug:
            e._finalize(scope)
